def find_lists(t):
    def count_lists(obj):
        count = 0
        if isinstance(obj, list):
            count += 1
            for item in obj:
                count += count_lists(item)
        elif isinstance(obj, tuple):
            for item in obj:
                count += count_lists(item)
        elif isinstance(obj, dict):
            for key, value in obj.items():
                count += count_lists(key)
                count += count_lists(value)
        elif isinstance(obj, set):
            for item in obj:
                count += count_lists(item)
        return count

    return count_lists(t)
